-- Read-only local/approved-hosted catalog checks; no data or grants changed.
select 'private_tables_force_rls' as check_name, case when count(*)=3 and bool_and(c.relrowsecurity and c.relforcerowsecurity and pg_get_userbyid(c.relowner)='fw_schema_owner') then 'PASS' else 'FAIL' end result
from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='private' and c.relname in ('work_integrity_events','work_integrity_receipts','work_passports')
union all select 'no_client_table_access',case when not exists(select 1 from (values('anon'),('authenticated'),('service_role')) r(role), (values('work_integrity_events'),('work_integrity_receipts'),('work_passports')) t(name) where has_table_privilege(r.role,'private.'||t.name,'SELECT,INSERT,UPDATE,DELETE')) then 'PASS' else 'FAIL' end
union all select 'no_client_private_helpers',case when not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace,(values('anon'),('authenticated'),('service_role')) r(role) where n.nspname='private' and p.proname in ('work_command_day5','read_work_day5','work_lock_owner','work_historical_authority','work_company_label','passport_eligible') and has_function_privilege(r.role,p.oid,'EXECUTE')) then 'PASS' else 'FAIL' end
union all select 'api_grants',case when count(*)=5 and bool_and(p.prosecdef and pg_get_userbyid(p.proowner)='fw_user_exec' and has_function_privilege('authenticated',p.oid,'EXECUTE') and not has_function_privilege('anon',p.oid,'EXECUTE') and not has_function_privilege('service_role',p.oid,'EXECUTE')) then 'PASS' else 'FAIL' end from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='api' and p.proname in ('work_command','read_work','work_integrity','initialize_passport','read_passport')
union all select 'immutable_integrity_history',case when count(*)=3 then 'PASS' else 'FAIL' end from pg_trigger where tgname in ('integrity_immutable','integrity_receipt_immutable','passport_immutable') and tgenabled='O'
union all select 'no_executor_schema_create',case when not has_schema_privilege('fw_user_exec','private','CREATE') and not has_schema_privilege('fw_policy_exec','private','CREATE') and not has_schema_privilege('fw_user_exec','api','CREATE') then 'PASS' else 'FAIL' end;
